import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class SummaryStatistics_addValue_TriageGen0Test {

    private SummaryStatistics stats;

    @Before
    public void setUp() {
        stats = new SummaryStatistics();
    }

    @Test
    public void testAddValue_BasicFunctionality() {
        stats.addValue(10.0);
        stats.addValue(20.0);

        assertEquals(2, stats.getN());
        assertEquals(30.0, stats.getSum(), 1e-10);
        assertEquals(500.0, stats.getSumsq(), 1e-10);
        assertEquals(15.0, stats.getMean(), 1e-10);
        assertEquals(10.0, stats.getMin(), 1e-10);
        assertEquals(20.0, stats.getMax(), 1e-10);
    }

    @Test
    public void testAddValue_BranchCoverage_WithOverrides() {
        // To maximize branch coverage, we need to trigger the 'if' conditions.
        // The code says: if (!(meanImpl instanceof Mean)) { meanImpl.increment(value); }
        // This means if the implementation IS an instance of Mean, increment is NOT called.
        // If it is NOT an instance of Mean, increment IS called.

        // Default implementation of SummaryStatistics uses specific classes.
        // We will mock the implementations to force the branches.

        SummaryStatistics customStats = new SummaryStatistics();

        // Create mocks
        StorelessUnivariateStatistic mockSum = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockSumsq = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockMin = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockMax = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockSumLog = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockSecondMoment = mock(StorelessUnivariateStatistic.class);

        // These are the ones with conditional logic
        Mean mockMean = mock(Mean.class); // instanceof Mean is true
        Variance mockVariance = mock(Variance.class); // instanceof Variance is true
        GeometricMean mockGeoMean = mock(GeometricMean.class); // instanceof GeometricMean is true

        // These are NOT the specific types, so increment SHOULD be called
        StorelessUnivariateStatistic nonMeanImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic nonVarianceImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic nonGeoMeanImpl = mock(StorelessUnivariateStatistic.class);

        customStats.setSumImpl(mockSum);
        customStats.setSumsqImpl(mockSumsq);
        customStats.setMinImpl(mockMin);
        customStats.setMaxImpl(mockMax);
        customStats.setSumLogImpl(mockSumLog);
        // Note: secondMoment is a field, not a setter in provided API, 
        // but usually handled via internal implementations. 
        // Assuming we can't set secondMoment directly via setter from snippet, 
        // we rely on standard flow for that part.

        customStats.setMeanImpl(mockMean); // Will trigger: !(mockMean instanceof Mean) -> false
        customStats.setVarianceImpl(mockVariance); // Will trigger: !(mockVariance instanceof Variance) -> false
        customStats.setGeoMeanImpl(mockGeoMean); // Will trigger: !(mockGeoMean instanceof GeometricMean) -> false

        // To hit the 'true' branches of the if-statements:
        // We need to replace them with objects that are NOT instances of Mean/Variance/GeometricMean
        customStats.setMeanImpl(nonMeanImpl);
        customStats.setVarianceImpl(nonVarianceImpl);
        customStats.setGeoMeanImpl(nonGeoMeanImpl);

        double val = 5.0;
        customStats.addValue(val);

        // Verify standard increments
        verify(mockSum, times(1)).increment(val);
        verify(mockSumsq, times(1)).increment(val);
        verify(mockMin, times(1)).increment(val);
        verify(mockMax, times(1)).increment(val);
        verify(mockSumLog, times(1)).increment(val);

        // Verify conditional increments (the 'true' branches)
        verify(nonMeanImpl, times(1)).increment(val);
        verify(nonVarianceImpl, times(1)).increment(val);
        verify(nonGeoMeanImpl, times(1)).increment(val);

        // Verify that the Mean-instance objects were NOT incremented (the 'false' branches)
        verify(mockMean, never()).increment(anyDouble());
        verify(mockVariance, never()).increment(anyDouble());
        verify(mockGeoMean, never()).increment(anyDouble());
    }

    @Test
    public void testAddValue_NegativeValues() {
        stats.addValue(-10.0);
        stats.addValue(-20.0);

        assertEquals(2, stats.getN());
        assertEquals(-30.0, stats.getSum(), 1e-10);
        assertEquals(-20.0, stats.getMax(), 1e-10);
        assertEquals(-20.0, stats.getMin(), 1e-10);
    }

    @Test
    public void testAddValue_Zero() {
        stats.addValue(0.0);
        assertEquals(1, stats.getN());
        assertEquals(0.0, stats.getSum(), 1e-10);
        assertEquals(0.0, stats.getMean(), 1e-10);
    }
}
